const DB_PREFIX='seeker-notebook-3:',GUEST_DB=`${DB_PREFIX}guest`,wallpaperJobs=new WeakMap;let wallpaperUrl=null,previewUrl=null;function requestResult(r){return new Promise((o,e)=>{r.onsuccess=()=>o(r.result);r.onerror=()=>e(r.error)})}function openNamedDb(n){return new Promise((o,e)=>{const r=indexedDB.open(n);r.onsuccess=()=>o(r.result);r.onerror=()=>e(r.error)})}async function activeDb(){const g=await openNamedDb(GUEST_DB);try{if(!g.objectStoreNames.contains('meta'))return g;const t=g.transaction('meta','readonly'),a=await requestResult(t.objectStore('meta').get('active-account'));if(!a?.value)return g;g.close();return await openNamedDb(`${DB_PREFIX}${a.value}`)}catch{return g}}async function getFromStore(db,s,id){if(!db.objectStoreNames.contains(s))return;return await requestResult(db.transaction(s,'readonly').objectStore(s).get(id))}function waitForTransaction(tx){return new Promise((o,e)=>{tx.oncomplete=()=>o();tx.onerror=()=>e(tx.error);tx.onabort=()=>e(tx.error||new Error('Сохранение прервано'))})}async function waitForParty(db,id){for(let a=0;a<30;a++){const r=await getFromStore(db,'records',id);if(r)return r;await new Promise(o=>setTimeout(o,60))}}async function imageBlob(file,maxSide,quality){const url=URL.createObjectURL(file);try{const image=new Image;image.src=url;await image.decode();const scale=Math.min(1,maxSide/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d',{alpha:false});if(!context)throw new Error('Не удалось подготовить изображение');context.drawImage(image,0,0,canvas.width,canvas.height);return await new Promise((o,e)=>canvas.toBlob(b=>b?o(b):e(new Error('Не удалось обработать изображение')),'image/jpeg',quality))}finally{URL.revokeObjectURL(url)}}async function prepareWallpaper(file){if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))throw new Error('Выберите JPEG, PNG, WebP или GIF.');if(file.size>20971520)throw new Error('Размер изображения должен быть меньше 20 МБ.');const id=crypto.randomUUID();return{id,blob:await imageBlob(file,1920,.84),thumbnail:await imageBlob(file,640,.8),mime:'image/jpeg',upload_state:'pending'}}async function currentPartyRecord(form){const id=form.dataset.id;if(!id)return;const db=await activeDb();try{return await getFromStore(db,'records',id)}finally{db.close()}}function wallpaperField(){const s=document.createElement('div');s.className='upload-section full wallpaper-upload-section';s.innerHTML=`<div class="section-label"><i></i><span>Обои партии</span><i></i></div><div class="wallpaper-upload-card"><label class="wallpaper-preview" aria-label="Выбрать обои партии"><span class="wallpaper-preview-mark">＋</span><input data-party-wallpaper-input type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label><div class="wallpaper-upload-copy"><strong>Фон журнала партии</strong><span>Выберите изображение. Оно появится за пергаментом только внутри этой партии.</span><label class="wallpaper-trigger">Выбрать изображение<input data-party-wallpaper-trigger type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label><small class="wallpaper-name">JPG, PNG, WEBP или GIF · до 20 МБ</small><button class="wallpaper-remove" type="button" hidden>Убрать обои</button></div></div>`;return s}function setPreview(section,file){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);const p=section.querySelector('.wallpaper-preview');if(p){p.style.backgroundImage=`linear-gradient(rgba(15,26,20,.12),rgba(15,26,20,.12)),url("${previewUrl}")`;p.classList.add('has-preview')}const n=section.querySelector('.wallpaper-name');if(n)n.textContent=file.name}async function hydrateWallpaperControl(form,section){const r=await currentPartyRecord(form);if(!r?.wallpaper_id)return;const db=await activeDb();try{const m=await getFromStore(db,'media',String(r.wallpaper_id));if(!m?.blob)return;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(m.thumbnail||m.blob);const p=section.querySelector('.wallpaper-preview');if(p){p.style.backgroundImage=`linear-gradient(rgba(15,26,20,.10),rgba(15,26,20,.10)),url("${previewUrl}")`;p.classList.add('has-preview')}const n=section.querySelector('.wallpaper-name');if(n)n.textContent='Обои установлены';const b=section.querySelector('.wallpaper-remove');if(b)b.hidden=false}finally{db.close()}}function connectWallpaperForm(form){if(form.dataset.partyWallpaperReady||form.dataset.type!=='party')return;form.dataset.partyWallpaperReady='true';if(!form.dataset.id)form.dataset.id=crypto.randomUUID();const section=wallpaperField(),error=form.querySelector('.form-error');error?error.before(section):form.append(section);void hydrateWallpaperControl(form,section);const inputs=[...section.querySelectorAll('input[type=file]')],useFile=file=>{if(!file)return;form.dataset.wallpaperRemove='false';setPreview(section,file);const job=prepareWallpaper(file).catch(error=>{const m=form.querySelector('.form-error');if(m)m.textContent=error instanceof Error?error.message:'Не удалось обработать обои';throw error});wallpaperJobs.set(form,job);const remove=section.querySelector('.wallpaper-remove');if(remove)remove.hidden=false};inputs.forEach(input=>input.addEventListener('change',()=>useFile(input.files?.[0])));section.querySelector('.wallpaper-remove')?.addEventListener('click',()=>{form.dataset.wallpaperRemove='true';wallpaperJobs.delete(form);inputs.forEach(input=>input.value='');const p=section.querySelector('.wallpaper-preview');if(p){p.style.backgroundImage='';p.classList.remove('has-preview')}const n=section.querySelector('.wallpaper-name');if(n)n.textContent='Обои будут удалены после сохранения'});form.addEventListener('submit',()=>void persistWallpaper(form))}async function persistWallpaper(form){const remove=form.dataset.wallpaperRemove==='true',job=wallpaperJobs.get(form);if(!remove&&!job)return;const id=form.dataset.id;if(!id)return;try{const media=remove?null:await job,db=await activeDb();try{const record=await waitForParty(db,id);if(!record)throw new Error('Партия ещё не сохранена');const tx=db.transaction(['records','media'],'readwrite'),next={...record,wallpaper_id:media?.id||null,updated_at:new Date().toISOString(),version:Number(record.version||0)+1};tx.objectStore('records').put(next);if(media)tx.objectStore('media').put(media);await waitForTransaction(tx)}finally{db.close()}if(location.hash===`#party/${id}`)window.dispatchEvent(new HashChangeEvent('hashchange'))}catch(error){console.error('Party wallpaper save failed',error)}}function compactPartyDetails(root=document){root.querySelectorAll('.detail-page .journal-section[data-section]').forEach(section=>{const id=section.dataset.section||'';if(/:(history|events|notes|companions)$/.test(id))section.remove()})}async function applyPartyWallpaper(root=document){const page=root instanceof HTMLElement&&root.matches('.detail-page')?root:root.querySelector('.detail-page');if(!page)return;const match=decodeURIComponent(location.hash).match(/^#party\/(.+)$/);if(!match)return;const db=await activeDb();try{const record=await getFromStore(db,'records',match[1]),wallpaperId=record?.wallpaper_id?String(record.wallpaper_id):'';if(!wallpaperId){page.classList.remove('has-party-wallpaper');page.style.removeProperty('--party-wallpaper');return}const media=await getFromStore(db,'media',wallpaperId);if(!media?.blob)return;if(wallpaperUrl)URL.revokeObjectURL(wallpaperUrl);wallpaperUrl=URL.createObjectURL(media.blob);page.style.setProperty('--party-wallpaper',`url("${wallpaperUrl}")`);page.classList.add('has-party-wallpaper')}finally{db.close()}}function optimizeImages(root=document){root.querySelectorAll('.campaign-card img, .session-card img, .detail-banner img').forEach((image,index)=>{image.decoding='async';if(!image.closest('.detail-banner')&&index>0)image.loading='lazy'})}function upgrade(root=document){if(root instanceof HTMLFormElement)connectWallpaperForm(root);root.querySelectorAll?.('#record-form[data-type="party"]').forEach(connectWallpaperForm);compactPartyDetails(root);optimizeImages(root);void applyPartyWallpaper(root)}upgrade();new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node instanceof HTMLElement)upgrade(node)}).observe(document.documentElement,{childList:true,subtree:true});addEventListener('hashchange',()=>{compactPartyDetails();void applyPartyWallpaper()});